// src/components/User/HomePage.js

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { categories } from '../../mockData';
import './HomePage.css';

// Search Icon Component
function SearchIcon() {
  return (
    <svg className="search-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" />
    </svg>
  );
}

// Main HomePage Component
function HomePage({ menu = [], cart = [], addToCart }) {
  const navigate = useNavigate();
  const [activeCategory, setActiveCategory] = useState(categories[0]);
  const [searchTerm, setSearchTerm] = useState('');

  // 1. Filter by Search Term
  const searchedMenu = menu.filter((item) =>
    item.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // 2. Group the searched menu by category
  const menuByCategories = categories.map((category) => ({
    categoryName: category,
    items: searchedMenu.filter((item) => item.category === category),
  }));

  // Calculate cart total
  const cartTotalItems = cart.reduce((acc, item) => acc + item.quantity, 0);

  return (
    <div className="mobile-container homepage">
      
      {/* Header */}
      <header className="home-header">
        <h1>Hello, Guest</h1>
        <p>What would you like to eat today?</p>
      </header>

      {/* Search Bar */}
      <div className="search-bar">
        <SearchIcon />
        <input
          type="text"
          placeholder="Search for food..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Category Navigation */}
      <nav className="category-nav">
        {categories.map((category) => (
          <button
            key={category}
            className={`category-btn ${activeCategory === category ? 'active' : ''}`}
            onClick={() => setActiveCategory(category)}
          >
            {category}
          </button>
        ))}
      </nav>

      {/* Menu List */}
      <section className="menu-list">
        {menuByCategories.map(({ categoryName, items }) => {
          // Only render the category section if it's the active one
          if (categoryName !== activeCategory) {
            return null;
          }
          
          return (
            <div key={categoryName} id={categoryName} className="category-section">
              <h2>{categoryName}</h2>
              {items.length > 0 ? (
                items.map((item) => (
                  <div key={item.id} className="menu-item">
                    <img src={item.image} alt={item.name} className="item-image" />
                    <div className="item-details">
                      <h3>{item.name}</h3>
                      <p>₹{item.price}</p>
                      {/* 👈 FIX IS HERE: BUTTON IS NOW INSIDE ITEM-DETAILS */}
                      <button className="add-btn" onClick={() => addToCart(item)}>+</button>
                    </div>
                  </div>
                ))
              ) : (
                <p>No items found in this category.</p>
              )}
            </div>
          );
        })}
      </section>

      {/* "Next" Button - only shows if cart has items */}
      {cartTotalItems > 0 && (
        <div className="next-button-container">
          <button className="next-btn" onClick={() => navigate('/checkout')}>
            <span>{cartTotalItems} Item{cartTotalItems > 1 ? 's' : ''}</span>
            <span>Next →</span>
          </button>
        </div>
      )}

    </div>
  );
}

export default HomePage;
